  const logo = chalk.hex(LOGO_COLOR);
  const maxWidth = Math.max(...LOGO_LINES.map(line => line.length));

  return LOGO_LINES
    .map((line, index) => {
      const logoLine = logo(line.padEnd(maxWidth));

      if (index !== SIGNATURE_LINE) {
        return logoLine;
